INSERT INTO `init_rtks_role` (`id`, `resource_id`, `name`, `description`, `create_time`, `update_time`, `level_id`, `category`, `task_ids`, `knowledge_id_weights`, `knowledge_ids`, `skill_id_weights`, `skill_ids`, `ability_ids`, `skill_courses`, `knowledge_courses`) VALUES (224, '04a48a4673f438fcd8df66d4267be4bc', 'Cyber Ops Planner', 'Develops detailed plans for the conduct or support of the applicable range of cyber operations through collaboration with other planners, operators and/or analysts. Participates in targeting selection, validation, synchronization, and enables integration during the execution of cyber actions.', '2020-12-28 10:14:47', '2020-12-30 14:24:47', '11f509c91f7746d3e0539cc8b1f48a26', '', '[\"T0563\",\"T0571\",\"T0579\",\"T0581\",\"T0592\",\"T0622\",\"T0627\",\"T0628\",\"T0635\",\"T0640\",\"T0648\",\"T0654\",\"T0655\",\"T0658\",\"T0665\",\"T0667\",\"T0670\",\"T0672\",\"T0679\",\"T0680\",\"T0690\",\"T0699\",\"T0703\",\"T0704\",\"T0719\",\"T0732\",\"T0733\",\"T0734\",\"T0739\",\"T0741\",\"T0742\",\"T0743\",\"T0747\",\"T0763\",\"T0764\",\"T0772\",\"T0787\",\"T0791\",\"T0795\",\"T0801\",\"T0813\",\"T0823\",\"T0836\"]', '[{\"id\":\"K0001\",\"weight\":1},{\"id\":\"K0002\",\"weight\":1},{\"id\":\"K0003\",\"weight\":1},{\"id\":\"K0004\",\"weight\":1},{\"id\":\"K0005\",\"weight\":1},{\"id\":\"K0006\",\"weight\":1},{\"id\":\"K0036\",\"weight\":1},{\"id\":\"K0108\",\"weight\":1},{\"id\":\"K0109\",\"weight\":1},{\"id\":\"K0347\",\"weight\":1},{\"id\":\"K0349\",\"weight\":1},{\"id\":\"K0350\",\"weight\":1},{\"id\":\"K0352\",\"weight\":1}]', '[\"K0001\",\"K0002\",\"K0003\",\"K0004\",\"K0005\",\"K0006\",\"K0036\",\"K0108\",\"K0109\",\"K0347\",\"K0349\",\"K0350\",\"K0352\"]', '[]', '[]', '[]', '[]', '[]');
INSERT INTO `init_rtks_role` (`id`, `resource_id`, `name`, `description`, `create_time`, `update_time`, `level_id`, `category`, `task_ids`, `knowledge_id_weights`, `knowledge_ids`, `skill_id_weights`, `skill_ids`, `ability_ids`, `skill_courses`, `knowledge_courses`) VALUES (225, '6163ce4394aa4d7a160a5b4bb6f64a0a', 'Partner Integration Planner', 'Works to advance cooperation across organizational or national borders between cyber operations partners. Aids the integration of partner cyber teams by providing guidance, resources, and collaboration to develop best practices and facilitate organizational support for achieving objectives in integrated cyber actions.', '2020-12-28 10:15:24', '2020-12-28 10:15:24', '11f509c91f7746d3e0539cc8b1f48a26', '', '[]', '[]', '[]', '[]', '[]', '[]', '[]', '[]');
INSERT INTO `init_rtks_role` (`id`, `resource_id`, `name`, `description`, `create_time`, `update_time`, `level_id`, `category`, `task_ids`, `knowledge_id_weights`, `knowledge_ids`, `skill_id_weights`, `skill_ids`, `ability_ids`, `skill_courses`, `knowledge_courses`) VALUES (226, '42516548ff9f7e540e1c4b0c3813e769', 'Cyber Operator', 'Conducts collection, processing, and/or geolocation of systems to exploit, locate, and/or track targets of interest. Performs network navigation, tactical forensic analysis, and, when directed, executes on-net operations.', '2020-12-28 10:16:01', '2020-12-28 10:16:01', '4af93b9117b121036846512cecee6548', '', '[]', '[]', '[]', '[]', '[]', '[]', '[]', '[]');
