INSERT INTO `init_rtks_role` (`id`, `resource_id`, `name`, `description`, `create_time`, `update_time`, `level_id`, `category`, `task_ids`, `knowledge_id_weights`, `knowledge_ids`, `skill_id_weights`, `skill_ids`, `ability_ids`, `skill_courses`, `knowledge_courses`) VALUES (228, '83325807c4cb85a0db778c3243f74b11', 'Law Enforcement/Counterintelligence Forensics Analyst', 'Conducts detailed investigations on computer-based crimes establishing documentary or physical evidence, to include digital media and logs associated with cyber intrusion incidents.', '2020-12-28 10:17:20', '2020-12-28 10:17:20', '6cfc850f773474b70d92d6817f721d69', '', '[]', '[]', '[]', '[]', '[]', '[]', '[]', '[]');
INSERT INTO `init_rtks_role` (`id`, `resource_id`, `name`, `description`, `create_time`, `update_time`, `level_id`, `category`, `task_ids`, `knowledge_id_weights`, `knowledge_ids`, `skill_id_weights`, `skill_ids`, `ability_ids`, `skill_courses`, `knowledge_courses`) VALUES (229, '3727d961d93316e18431ea403b19e1f8', 'Cyber Defense Forensics Analyst', 'Analyzes digital evidence and investigates computer security incidents to derive useful information in support of system/network vulnerability mitigation.', '2020-12-28 10:17:46', '2020-12-28 10:17:46', '6cfc850f773474b70d92d6817f721d69', '', '[]', '[]', '[]', '[]', '[]', '[]', '[]', '[]');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (134, 'T0001', 'Acquire and manage the necessary resources, including leadership support, financial  resources, and key security personnel, to support information technology (IT) security goals  and objectives and reduce overall organizational risk.', '2020-12-24 09:23:31', '2020-12-24 09:23:31');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (135, 'T0002', 'Acquire necessary resources, including financial resources, to conduct an effective  enterprise continuity of operations program.', '2020-12-24 09:23:49', '2020-12-24 09:23:49');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (136, 'T0003', 'Advise senior management (e.g., Chief Information Officer [CIO]) on risk levels and security posture.', '2020-12-24 09:24:08', '2020-12-24 09:24:08');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (137, 'T0004', 'Advise senior management (e.g., CIO) on cost/benefit analysis of information security  programs, policies, processes, systems, and elements.', '2020-12-24 09:24:35', '2020-12-24 09:24:35');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (138, 'T0005', 'Advise appropriate senior leadership or Authorizing Official of changes affecting the  organization\'s cybersecurity posture.', '2020-12-24 09:24:54', '2020-12-24 09:24:54');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (139, 'T0006', 'Advocate organization\'s official position in legal and legislative proceedings.', '2020-12-24 09:25:12', '2020-12-24 09:25:12');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (140, 'T0007', 'Analyze and define data requirements and specifications.', '2020-12-24 09:25:28', '2020-12-24 09:25:28');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (141, 'T0008', 'Analyze and plan for anticipated changes in data capacity requirements.', '2020-12-24 09:25:48', '2020-12-24 09:25:48');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (142, 'T0009', 'Analyze information to determine, recommend, and plan the development of a new  application or modification of an existing application.', '2020-12-24 09:26:06', '2020-12-24 09:26:06');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (143, 'T0010', 'Analyze organization\'s cyber defense policies and configurations and evaluate compliance  with regulations and organizational directives.', '2020-12-24 09:26:26', '2020-12-24 09:26:26');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (144, 'T0011', 'Analyze user needs and software requirements to determine feasibility of design within time  and cost constraints.', '2020-12-24 09:26:42', '2020-12-24 09:26:42');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (145, 'T0012', 'Analyze design constraints, analyze trade-offs and detailed system and security design, and  consider life cycle support.', '2020-12-24 09:26:59', '2020-12-24 09:26:59');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (146, 'T0013', 'Apply coding and testing standards, apply security testing tools including \"\'fuzzing\" staticanalysis code scanning tools, and conduct code reviews.', '2020-12-24 09:27:17', '2020-12-24 09:27:17');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (147, 'T0014', 'Apply secure code documentation.', '2020-12-24 09:27:31', '2020-12-24 09:27:31');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (148, 'T0015', 'Apply security policies to applications that interface with one another, such as Business-toBusiness (B2B) applications.', '2020-12-24 09:27:50', '2020-12-24 09:27:50');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (149, 'T0016', 'Apply security policies to meet security objectives of the system.', '2020-12-24 09:28:06', '2020-12-24 09:28:06');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (150, 'T0017', 'Apply service-oriented security architecture principles to meet organization\'s  confidentiality, integrity, and availability requirements.', '2020-12-24 09:29:11', '2020-12-24 09:29:11');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (151, 'T0018', 'Assess the effectiveness of cybersecurity measures utilized by system(s).', '2020-12-24 09:29:25', '2020-12-24 09:29:25');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (152, 'T0019', 'Assess threats to and vulnerabilities of computer system(s) to develop a security risk profile.', '2020-12-24 09:29:41', '2020-12-24 09:29:41');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (153, 'T0020', 'Develop content for cyber defense tools.', '2020-12-24 09:29:57', '2020-12-24 09:29:57');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (154, 'T0021', 'Build, test, and modify product prototypes using working models or theoretical models.', '2020-12-24 09:30:11', '2020-12-24 09:30:11');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (155, 'T0022', 'Capture security controls used during the requirements phase to integrate security within the  process, to identify key security objectives, and to maximize software security while  minimizing disruption to plans and schedules.', '2020-12-24 09:30:26', '2020-12-24 09:30:26');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (156, 'T0023', 'Characterize and analyze network traffic to identify anomalous activity and potential threats  to network resources.', '2020-12-24 09:31:10', '2020-12-24 09:31:10');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (157, 'T0024', 'Collect and maintain data needed to meet system cybersecurity reporting.', '2020-12-24 09:34:15', '2020-12-24 09:34:15');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (158, 'T0025', 'Communicate the value of information technology (IT) security throughout all levels of the  organization stakeholders.', '2020-12-24 09:34:33', '2020-12-24 09:34:33');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (159, 'T0026', 'Compile and write documentation of program development and subsequent revisions,  inserting comments in the coded instructions so others can understand the program.', '2020-12-24 09:34:51', '2020-12-24 09:34:51');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (160, 'T0027', 'Conduct analysis of log files, evidence, and other information to determine best methods for  identifying the perpetrator(s) of a network intrusion.', '2020-12-24 09:52:07', '2020-12-24 09:52:07');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (161, 'T0028', 'Conduct and/or support authorized penetration testing on enterprise network assets.', '2020-12-24 09:52:31', '2020-12-24 09:52:31');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (162, 'T0029', 'Conduct functional and connectivity testing to ensure continuing operability.', '2020-12-24 09:52:48', '2020-12-24 09:52:48');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (163, 'T0030', 'Conduct interactive training exercises to create an effective learning environment.', '2020-12-24 09:53:07', '2020-12-24 09:53:07');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (164, 'T0031', 'Conduct interviews of victims and witnesses and conduct interviews or interrogations of  suspects.', '2020-12-24 09:53:21', '2020-12-24 09:53:21');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (165, 'T0032', 'Conduct Privacy Impact Assessments (PIAs) of the application’s security design for the  appropriate security controls, which protect the confidentiality and integrity of Personally  Identifiable Information (PII).', '2020-12-24 09:53:34', '2020-12-24 09:53:34');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (166, 'T0033', 'Conduct risk analysis, feasibility study, and/or trade-off analysis to develop, document, and  refine functional requirements and specifications.', '2020-12-24 09:53:50', '2020-12-24 09:53:50');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (167, 'T0034', 'Confer with systems analysts, engineers, programmers, and others to design application and  to obtain information on project limitations and capabilities, performance requirements, and  interfaces.', '2020-12-24 09:54:05', '2020-12-24 09:54:05');
INSERT INTO `init_rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (168, 'T0035', 'Configure and optimize network hubs, routers, and switches (e.g., higher-level protocols,  tunneling).', '2020-12-24 09:54:22', '2020-12-24 09:54:22');
