INSERT INTO `rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (1084, 'T0954', 'Conduct initial remediation actions on security controls based on the findings and  recommendations of a security assessment report; reassess remediated controls.', '2020-12-27 15:22:08', '2020-12-27 15:22:08');
INSERT INTO `rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (1085, 'T0955', 'Prepare a plan of action and milestones based on the findings and recommendations of a security assessment report excluding any remediation actions taken.', '2020-12-27 15:22:22', '2020-12-27 15:22:22');
INSERT INTO `rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (1086, 'T0956', 'Assemble an authorization package and submit the package to an authorizing official for  adjudication.', '2020-12-27 15:22:36', '2020-12-27 15:22:36');
INSERT INTO `rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (1087, 'T0957', 'Determine the risk from the operation or use of a system or the provision or use of common  controls.', '2020-12-27 15:22:56', '2020-12-27 15:22:56');
INSERT INTO `rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (1088, 'T0958', 'Identify and implement a preferred course of action in response to the risk determined.', '2020-12-27 15:23:15', '2020-12-27 15:23:15');
INSERT INTO `rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (1089, 'T0959', 'Determine if the risk from the operation or use of the system or the provision or use of  common controls, is acceptable.', '2020-12-27 15:23:44', '2020-12-27 15:23:44');
INSERT INTO `rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (1090, 'T0960', 'Monitor changes to a system and its environment of operation.', '2020-12-27 15:24:08', '2020-12-27 15:24:08');
INSERT INTO `rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (1091, 'T0961', 'Assess the security controls employed within and inherited by the system in accordance  with an organization-defined monitoring strategy.', '2020-12-27 15:24:35', '2020-12-27 15:24:35');
INSERT INTO `rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (1092, 'T0962', 'Respond to risk based on the results of ongoing monitoring activities, assessment of risk,  and outstanding items in a plan of action and milestones.', '2020-12-27 15:24:55', '2020-12-27 15:24:55');
INSERT INTO `rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (1093, 'T0963', 'Update a security plan, security assessment report, and plan of action and milestones based  on the results of a continuous monitoring process.', '2020-12-27 15:26:27', '2020-12-27 15:26:27');
INSERT INTO `rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (1094, 'T0964', 'Report the security status of a system (including the effectiveness of security controls) to an authorizing official on an ongoing basis in accordance with the monitoring strategy.', '2020-12-27 15:26:43', '2020-12-27 15:26:43');
INSERT INTO `rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (1095, 'T0965', 'Review the security status of a system (including the effectiveness of security controls) on  an ongoing basis to determine whether the risk remains acceptable.', '2020-12-27 15:27:04', '2020-12-27 15:27:04');
INSERT INTO `rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (1096, 'T0966', 'Implement a system disposal strategy which executes required actions when a system is  removed from service.', '2020-12-27 15:27:38', '2020-12-27 15:27:38');
INSERT INTO `rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (1097, 'T0967', 'Sponsor and promote continuous monitoring within the organization.', '2020-12-27 15:28:01', '2020-12-27 15:28:01');
