INSERT INTO `rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (1102, 'T0972', 'Use continuous monitoring scoring and grading metrics to make information security  investment decisions to address persistent issues.', '2020-12-27 15:29:49', '2020-12-27 15:29:49');
INSERT INTO `rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (1103, 'T0973', 'Ensure that the continuous monitoring staff have the training and resources (e.g., staff and  budget) needed to perform assigned duties.', '2020-12-27 15:30:04', '2020-12-27 15:30:04');
