INSERT INTO `rtks_task` (`id`, `resource_id`, `content`, `create_time`, `update_time`) VALUES (1111, 'T0982', 'Identify security oriented organization reporting requirements that are fulfilled by the  continuous monitoring program.', '2020-12-27 15:33:07', '2020-12-27 15:33:07');
